CREATE TABLE IF NOT EXISTS report_definitions(code TEXT PRIMARY KEY,name TEXT NOT NULL,business_type TEXT NOT NULL,template_version TEXT NOT NULL,legacy_entry TEXT,schema_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS report_jobs(id TEXT PRIMARY KEY,definition_code TEXT NOT NULL,project_code TEXT NOT NULL,business_version_id TEXT NOT NULL,format TEXT NOT NULL,status TEXT NOT NULL,progress INTEGER NOT NULL,parameters_json TEXT NOT NULL,snapshot_json TEXT NOT NULL,error_json TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,row_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS report_artifacts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL,filename TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,content BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_download_audit(id TEXT PRIMARY KEY,artifact_id TEXT NOT NULL,actor TEXT NOT NULL,downloaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS setting_definitions(key TEXT PRIMARY KEY,category TEXT NOT NULL,value_type TEXT NOT NULL,default_json TEXT NOT NULL,constraints_json TEXT NOT NULL,version INTEGER NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS setting_values(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,row_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS admin_groups(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_group_members(group_id TEXT NOT NULL,user_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS backup_runs(id TEXT PRIMARY KEY,status TEXT NOT NULL,database_url TEXT NOT NULL,sha256 TEXT,size_bytes INTEGER,artifact BLOB,precheck_json TEXT NOT NULL,smoke_json TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT,row_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS admin_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
